package contracts

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.{AtomicLong, AtomicInteger}
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

case class Transaction(sender: String, recipient: String, amount: BigDecimal, nonce: Long, timestamp: Long)

case class RateLimitEntry(windowStart: AtomicLong, requestCount: AtomicInteger) {
  def reset(now: Long): Unit = {
    windowStart.set(now)
    requestCount.set(0)
  }
}

trait RateLimitPolicy {
  def maxRequestsPerWindow: Int
  def windowDurationMs: Long
  def retryBackoffMs: Long
  def maxRetries: Int
}

object DefaultPolicy extends RateLimitPolicy {
  val maxRequestsPerWindow: Int = 10
  val windowDurationMs: Long = 60000L
  val retryBackoffMs: Long = 1000L
  val maxRetries: Int = 3
}

class SmartContractEngine(policy: RateLimitPolicy = DefaultPolicy) {
  private val balances = TrieMap[String, BigDecimal]()
  private val rateLimits = new ConcurrentHashMap[String, RateLimitEntry]()
  private val nonceTracker = TrieMap[String, Long]()
  private val pendingRetries = TrieMap[String, AtomicInteger]()

  def initAccount(address: String, initialBalance: BigDecimal): Unit = {
    balances.putIfAbsent(address, initialBalance)
    nonceTracker.putIfAbsent(address, 0L)
  }

  private def getOrCreateRateLimit(sender: String): RateLimitEntry = {
    rateLimits.computeIfAbsent(sender, _ => RateLimitEntry(new AtomicLong(System.currentTimeMillis()), new AtomicInteger(0)))
  }

  private def checkRateLimit(sender: String): Boolean = {
    val entry = getOrCreateRateLimit(sender)
    val now = System.currentTimeMillis()
    val elapsed = now - entry.windowStart.get()

    if (elapsed >= policy.windowDurationMs) {
      entry.reset(now)
    }

    val currentCount = entry.requestCount.get()
    if (currentCount < policy.maxRequestsPerWindow) {
      entry.requestCount.incrementAndGet()
      true
    } else {
      false
    }
  }

  private def validateNonce(sender: String, nonce: Long): Boolean = {
    val expected = nonceTracker.getOrElse(sender, 0L)
    nonce == expected
  }

  private def incrementNonce(sender: String): Unit = {
    nonceTracker.updateWith(sender) {
      case Some(n) => Some(n + 1)
      case None => Some(1L)
    }
  }

  private def executeTransfer(tx: Transaction): Either[String, String] = {
    val senderBalance = balances.getOrElse(tx.sender, BigDecimal(0))
    if (senderBalance < tx.amount) {
      Left("Insufficient balance")
    } else {
      balances.update(tx.sender, senderBalance - tx.amount)
      balances.updateWith(tx.recipient) {
        case Some(b) => Some(b + tx.amount)
        case None => Some(tx.amount)
      }
      incrementNonce(tx.sender)
      Right(s"Transfer of ${tx.amount} from ${tx.sender} to ${tx.recipient} confirmed")
    }
  }

  def submitTransaction(tx: Transaction): Either[String, String] = {
    submitWithRetry(tx, 0)
  }

  private def submitWithRetry(tx: Transaction, attempt: Int): Either[String, String] = {
    if (!validateNonce(tx.sender, tx.nonce)) {
      return Left(s"Invalid nonce: expected ${nonceTracker.getOrElse(tx.sender, 0L)}, got ${tx.nonce}")
    }

    if (checkRateLimit(tx.sender)) {
      executeTransfer(tx)
    } else {
      if (attempt < policy.maxRetries) {
        Thread.sleep(policy.retryBackoffMs)
        submitWithRetry(tx, attempt + 1)
      } else {
        Left("Rate limit exceeded, max retries exhausted")
      }
    }
  }

  def submitBatch(transactions: Seq[Transaction]): Seq[Either[String, String]] = {
    transactions.map { tx =>
      submitTransaction(tx)
    }
  }

  def getBalance(address: String): BigDecimal = balances.getOrElse(address, BigDecimal(0))
  def getNonce(address: String): Long = nonceTracker.getOrElse(address, 0L)

  def getRemainingQuota(sender: String): Int = {
    val entry = getOrCreateRateLimit(sender)
    val now = System.currentTimeMillis()
    val elapsed = now - entry.windowStart.get()
    if (elapsed >= policy.windowDurationMs) {
      policy.maxRequestsPerWindow
    } else {
      Math.max(0, policy.maxRequestsPerWindow - entry.requestCount.get())
    }
  }
}

object ContractApp extends App {
  val engine = new SmartContractEngine()
  engine.initAccount("alice", BigDecimal(1000))
  engine.initAccount("bob", BigDecimal(500))

  val tx = Transaction("alice", "bob", BigDecimal(50), 0L, System.currentTimeMillis())
  println(engine.submitTransaction(tx))
  println(s"Alice balance: ${engine.getBalance("alice")}")
  println(s"Bob balance: ${engine.getBalance("bob")}")
}
